// =====================================================
// FOLLOW-UP ENROLLMENT TRIGGER
// Called at every journedfdy step completion inside processConversationWithOptimizedCrew.
// Fires-and-forgets (caller uses .catch) so it never breaks the conversation.
// =====================================================

/**
 * Maps a completed DAIVE journey step to a follow-up lifecycle stage and
 * triggers immediate enrollment via followupAutomation.
 *
 * Step ? Lifecycle Stage ? Follow-Up Category mapping:
 *   lead_capture       ? new_lead         ? lead_nurture
 *   qualification      ? warm_lead        ? lead_nurture  (finance follow-ups)
 *   purchase_commitment ? purchased       ? post_purchase
 *   delivery           ? loyal_customer   ? long_term_loyalty
 *   csi_followup       ? loyal_customer   ? long_term_loyalty
 *
 * Steps NOT mapped here (handled separately or not applicable):
 *   inquiry, vehicle_selection, test_drive, trade_evaluation, vehicle_preparation, finance_manager
 *
 * unsold_visit is enrolled at handoff if no purchase_commitment ever fires.
 */
async function triggerFollowUpForStep(completedStep, conversationContext, customerInfo, dealerId) {
  const STEP_TO_STAGE = {
    lead_capture:        'new_lead',
    qualification:       'warm_lead',
    purchase_commitment: 'purchased',
    delivery:            'loyal_customer',
    csi_followup:        'loyal_customer',
  };

  const stage = STEP_TO_STAGE[completedStep];
  if (!stage) return; // step not mapped ? nothing to do

  // Guard: avoid duplicate triggers within the same conversation turn
  if (!conversationContext._followupTriggeredSteps) {
    conversationContext._followupTriggeredSteps = new Set();
  }
  const triggerKey = `${completedStep}:${stage}`;
  if (conversationContext._followupTriggeredSteps.has(triggerKey)) return;
  conversationContext._followupTriggeredSteps.add(triggerKey);

  const resolvedDealerId = dealerId ||
    conversationContext.dealerId ||
    customerInfo?.dealerId;

  if (!resolvedDealerId) {
    console.log('??  triggerFollowUpForStep: no dealerId available, skipping');
    return;
  }

  // Extract customer email from context (multiple possible slots)
  const customerEmail =
    conversationContext.Daivesteps?.[2]?.slots?.customer_email ||
    conversationContext.Daivesteps?.[2]?.slots?.email ||
    conversationContext.customer_email ||
    customerInfo?.email ||
    null;

  const customerName =
    conversationContext.Daivesteps?.[2]?.slots?.customer_name ||
    conversationContext.Daivesteps?.[2]?.slots?.name ||
    conversationContext.customer_name ||
    customerInfo?.name ||
    'DAIVE Customer';

  const customerPhone =
    conversationContext.Daivesteps?.[2]?.slots?.customer_phone ||
    conversationContext.Daivesteps?.[2]?.slots?.phone ||
    conversationContext.customer_phone ||
    customerInfo?.phone ||
    null;

  const vehicleId =
    conversationContext.Daivesteps?.[3]?.slots?.VehicleSelection?.vehicleId ||
    conversationContext.Daivesteps?.[3]?.slots?.VehicleSelection?.id ||
    null;

  const conversationId = conversationContext.conversationId || null;

  console.log(`?? triggerFollowUpForStep: step=${completedStep} stage=${stage} dealer=${resolvedDealerId} email=${customerEmail}`);

  // If we already have a lead_id on the context (linked at handoff), use that
  const existingLeadId = conversationContext._followupLeadId || null;

  if (existingLeadId) {
    await followupAutomation.enrollLeadImmediately(existingLeadId, resolvedDealerId, stage, {
      customerEmail
    });
  } else if (customerEmail) {
    // Upsert lead and enroll ? stores resulting lead ID back on context for future steps
    const result = await followupAutomation.upsertLeadAndEnroll(
      resolvedDealerId,
      { name: customerName, email: customerEmail, phone: customerPhone, vehicleId },
      stage,
      conversationId
    );
    // Cache the lead id so subsequent step completions reuse it
    if (result?.leadId) {
      conversationContext._followupLeadId = result.leadId;
    }
  } else {
    console.log('??  triggerFollowUpForStep: no customer email in context, skipping enrollment');
  }
}

