// ML Intent Detector using Python scikit-learn model
class MLIntentDetector {
  constructor(modelPath = 'enhanced_intent_model.pkl') {
    this.modelPath = modelPath;
    this.pythonScript = null;
    this.createPythonScript();
  }

  createPythonScript() {
    this.pythonScript = `import sys
import pickle
import json

def predict_intent(message, model_path):
    try:
        # Load the trained model
        with open(model_path, 'rb') as f:
            model = pickle.load(f)
        
        # Make prediction
        prediction = model.predict([message.lower()])
        intent = prediction[0]
        
        # Get prediction probabilities
        probabilities = model.predict_proba([message.lower()])[0]
        confidence = max(probabilities) * 100
        
        # Map ML intents to our system
        intent_mapping = {
            'buy_car': 'purchase',
            'car_type_preference': 'car_type',
            'budget_inquiry': 'budget',
            'financing_options': 'financing',
            'feature_request': 'features',
            'car_comparison': 'comparison',
            'check_availability': 'availability',
            'ask_discounts': 'discounts',
            'after_sales': 'after_sales',
            'purchase_commitment': 'purchase_commitment'
        }
        
        mapped_intent = intent_mapping.get(intent, 'general_inquiry')
        
        result = {
            "intent": mapped_intent,
            "confidence": confidence,
            "method": "ml",
            "original_intent": intent
        }
        
        print(json.dumps(result))
        
    except Exception as e:
        error_result = {
            "error": str(e),
            "intent": "general_inquiry",
            "confidence": 0,
            "method": "error"
        }
        print(json.dumps(error_result))

if __name__ == "__main__":
    if len(sys.argv) != 3:
        print(json.dumps({"error": "Usage: python script.py <message> <model_path>", "intent": "general_inquiry", "confidence": 0, "method": "error"}))
        sys.exit(1)
    
    message = sys.argv[1]
    model_path = sys.argv[2]
    predict_intent(message, model_path)`;
  }

  async detectIntent(message, confidenceThreshold = 0.15) {
    return new Promise(async (resolve, reject) => {
      try {
        const { spawn } = await import('child_process');
        
        const pythonProcess = spawn('python', ['-c', this.pythonScript, message, this.modelPath]);
        
        let result = '';
        let error = '';
        
        pythonProcess.stdout.on('data', (data) => {
          result += data.toString();
        });
        
        pythonProcess.stderr.on('data', (data) => {
          error += data.toString();
        });
        
        pythonProcess.on('close', (code) => {
          if (code !== 0) {
            console.log(`?? ML detection failed with code ${code}: ${error}`);
            resolve({
              intent: 'general_inquiry',
              confidence: 0,
              method: 'fallback',
              error: error
            });
            return;
          }
          
          try {
            const parsedResult = JSON.parse(result.trim());
            
            if (parsedResult.error) {
              console.log(`?? ML detection error: ${parsedResult.error}`);
              resolve({
                intent: 'general_inquiry',
                confidence: 0,
                method: 'fallback',
                error: parsedResult.error
              });
              return;
            }
            
            // Check confidence threshold
            if (parsedResult.confidence >= confidenceThreshold * 100) {
              console.log(`? ML intent detected: ${parsedResult.intent} (${parsedResult.confidence.toFixed(2)}% confidence)`);
              resolve(parsedResult);
            } else {
              console.log(`?? ML confidence too low: ${parsedResult.confidence.toFixed(2)}% < ${confidenceThreshold * 100}%`);
              resolve({
                intent: 'general_inquiry',
                confidence: parsedResult.confidence,
                method: 'low_confidence',
                original_intent: parsedResult.intent
              });
            }
            
          } catch (parseError) {
            console.log(`?? Failed to parse ML result: ${parseError.message}`);
            resolve({
              intent: 'general_inquiry',
              confidence: 0,
              method: 'parse_error',
              error: parseError.message
            });
          }
        });
        
        pythonProcess.on('error', (err) => {
          console.log(`?? ML detection process error: ${err.message}`);
          resolve({
            intent: 'general_inquiry',
            confidence: 0,
            method: 'process_error',
            error: err.message
          });
        });
      } catch (error) {
        console.log(`?? ML detection setup error: ${error.message}`);
        resolve({
          intent: 'general_inquiry',
          confidence: 0,
          method: 'setup_error',
          error: error.message
        });
      }
    });
  }
}

// CrewAI ML Integration with caching and performance tracking
class CrewAIMLIntegration {
  constructor(options = {}) {
    this.mlDetector = new MLIntentDetector(options.modelPath || 'enhanced_intent_model.pkl');
    this.cache = new Map();
    this.cacheSize = options.cacheSize || 1000;
    this.cacheTTL = options.cacheTTL || 300000; // 5 minutes
    this.stats = {
      totalRequests: 0,
      cacheHits: 0,
      mlHits: 0,
      fallbacks: 0,
      averageResponseTime: 0,
      totalResponseTime: 0
    };
    this.confidenceThreshold = options.confidenceThreshold || 0.15;
  }

  async detectIntent(message, context = {}) {
    const startTime = Date.now();
    this.stats.totalRequests++;
    
    // Check cache first
    const cacheKey = message.toLowerCase().trim();
    const cachedResult = this.cache.get(cacheKey);
    
    if (cachedResult && (Date.now() - cachedResult.timestamp) < this.cacheTTL) {
      this.stats.cacheHits++;
      const responseTime = Date.now() - startTime;
      this.updateResponseTimeStats(responseTime);
      console.log(`? Cache hit for ML intent detection (${responseTime}ms)`);
      return cachedResult.result;
    }
    
    try {
      // Use ML detection
      const mlResult = await this.mlDetector.detectIntent(message, this.confidenceThreshold);
      this.stats.mlHits++;
      
      // Cache the result
      this.cache.set(cacheKey, {
        result: mlResult,
        timestamp: Date.now()
      });
      
      // Manage cache size
      if (this.cache.size > this.cacheSize) {
        const firstKey = this.cache.keys().next().value;
        this.cache.delete(firstKey);
      }
      
      const responseTime = Date.now() - startTime;
      this.updateResponseTimeStats(responseTime);
      
      console.log(`?? ML intent detection completed in ${responseTime}ms`);
      return mlResult;
      
    } catch (error) {
      this.stats.fallbacks++;
      console.log(`?? ML detection failed, using fallback: ${error.message}`);
      
      const fallbackResult = {
        intent: 'general_inquiry',
        confidence: 0,
        method: 'fallback',
        error: error.message
      };
      
      const responseTime = Date.now() - startTime;
      this.updateResponseTimeStats(responseTime);
      
      return fallbackResult;
    }
  }

  updateResponseTimeStats(responseTime) {
    this.stats.totalResponseTime += responseTime;
    this.stats.averageResponseTime = this.stats.totalResponseTime / this.stats.totalRequests;
  }

  getStats() {
    return {
      ...this.stats,
      cacheHitRate: this.stats.totalRequests > 0 ? (this.stats.cacheHits / this.stats.totalRequests * 100).toFixed(2) : 0,
      mlHitRate: this.stats.totalRequests > 0 ? (this.stats.mlHits / this.stats.totalRequests * 100).toFixed(2) : 0,
      fallbackRate: this.stats.totalRequests > 0 ? (this.stats.fallbacks / this.stats.totalRequests * 100).toFixed(2) : 0
    };
  }

  clearCache() {
    this.cache.clear();
    console.log('?? ML intent detection cache cleared');
  }
}

// Initialize ML integration
const mlIntegration = new CrewAIMLIntegration({
  modelPath: 'enhanced_intent_model.pkl',
  confidenceThreshold: 0.15,
  cacheSize: 1000,
  cacheTTL: 300000 // 5 minutes
});


