  // Combine responses from all agents
  combineAgentResponses(agentResponses) {
    let combinedResponse = "Based on our team's expertise, here's what we can offer you:\n\n";
    
    agentResponses.forEach(({ agent, response }) => {
      combinedResponse += `**${agent}:** ${response}\n\n`;
    });
    
    combinedResponse += "We're here to help you with every step of your vehicle purchase journey. Is there anything specific you'd like to know more about?";
    
    return combinedResponse;
  }

