  /**
   * ? ENHANCED: Ensure all responses have TTS generation with retry logic
   * This method wraps response objects to ensure they get audioUrl populated
   */
  async ensureTTSGeneration(responseObj, dealerId = null, retries = 2) {
    if (!responseObj || !responseObj.response) {
      console.warn('?? [TTS] No response object or response text provided');
      return responseObj;
    }

    // If audioUrl is already present, return as is
    if (responseObj.audioUrl) {
      console.log('? [TTS] Audio URL already present, skipping generation');
      return responseObj;
    }

    // Extract a concise TTS-friendly summary instead of sending the full response.
    // This avoids long delays when the LLM produces feature lists or comparisons.
    const ttsText = this.extractTTSSummary(responseObj.response, 350);
    console.log(`?? [TTS] Summary for speech (${ttsText.length} chars): "${ttsText.substring(0, 120)}..."`);

    let lastError = null;
    
    // Retry logic for TTS generation
    for (let attempt = 1; attempt <= retries + 1; attempt++) {
    try {
        console.log(`?? [TTS] Attempt ${attempt}/${retries + 1}: Generating TTS for response...`);
        
      const audioUrl = await this.generateTTSResponse(ttsText, dealerId);
      
        if (audioUrl) {
          console.log(`? [TTS] Successfully generated on attempt ${attempt}`);
          return {
            ...responseObj,
            audioUrl: audioUrl,
            audioResponseUrl: audioUrl,
            ttsGenerated: true,
            ttsAttempts: attempt
          };
        } else {
          // null means API key missing / provider not configured ? no point retrying
          console.warn(`?? [TTS] Attempt ${attempt} returned null (API key missing or provider not configured)`);
          return {
            ...responseObj,
            audioUrl: null,
            audioResponseUrl: null,
            ttsGenerated: false,
            ttsAttempts: attempt,
            ttsSkipReason: 'TTS returned null - API keys not configured or TTS disabled'
          };
        }
      } catch (error) {
        lastError = error;
        console.error(`? [TTS] Attempt ${attempt} failed:`, error.message);
        
        if (attempt < retries + 1) {
          const waitTime = attempt * 1000; // Exponential backoff: 1s, 2s
          console.log(`? [TTS] Waiting ${waitTime}ms before retry...`);
          await new Promise(resolve => setTimeout(resolve, waitTime));
        }
      }
    }
    
    // All retries failed
    console.error(`? [TTS] All ${retries + 1} attempts failed. Last error:`, lastError?.message);
    return {
      ...responseObj,
      audioUrl: null,
      audioResponseUrl: null,
      ttsGenerated: false,
      ttsAttempts: retries + 1,
      ttsError: lastError?.message
    };
  }

  // Process conversation with selected agent
  async processWithSelectedAgent(agentKey, userMessage, customerInfo, conversationState) {
    try {
      console.log(`?? Processing with ${agentKey} agent...`);
      
      if (!this.agents[agentKey]) {
        console.log(`?? Agent ${agentKey} not available, falling back to basic AI`);
        return await this.processWithAI(null, null, userMessage, customerInfo);
      }
      
      const agent = this.agents[agentKey];
      console.log(`????? Using ${agent.role} for response...`);
      
      // Build agent-specific prompt with mandatory slot status
      const agentPrompt = this.buildAgentPrompt(agent, userMessage, {
        ...customerInfo,
        conversationState,
        agentRole: agent.role,
        mandatorySlotsFilled: this.slotManager && conversationContext ? 
          (this.slotManager.initialize(conversationContext), this.slotManager.areMandatorySlotsFilled()) : false,
        nextEmptySlot: this.slotManager && conversationContext ? 
          (this.slotManager.initialize(conversationContext), this.slotManager.getNextEmptyMandatorySlot()) : null
      });
      
      // Get response from CrewAI LLM
      const response = await this.crewAI.invoke(agentPrompt);
      
      console.log(`? ${agentKey} agent response generated:`, response.content.substring(0, 100) + '...');
      
      return {
        response: response.content,
        hasInventory: false,
        crewUsed: true,
        crewType: `Agent_${agentKey}`,
        intent: this.detectIntent(userMessage),
        selectedAgent: agentKey,
        leadScore: this.calculateLeadScore(
          { intent: this.detectIntent(userMessage), urgency: this.assessUrgency(userMessage), message: userMessage },
          customerInfo?.conversationContext || null
        ),
        shouldHandoff: false, // legacy path ? context not available for tier evaluation
        audioResponseUrl: null // TTS not implemented for individual agent processing
      };
      
    } catch (error) {
      console.error(`? Error in ${agentKey} agent processing:`, error);
      console.error('? Error details:', error.stack);
      
      // Fallback to basic AI processing
      console.log('?? Falling back to basic AI processing...');
      return await this.processWithAI(null, null, userMessage, customerInfo);
    }
  }

