  // NEW: Initialize CrewAI LLM for a specific dealer
  async initializeCrewAI(dealerId) {
    try {
      console.log(`?? Initializing CrewAI for dealer: ${dealerId}`);
      
      // Try to get API key from the specified dealer first
      let openaiKey = null;
      
      if (this.settingsManager) {
        try {
          const apiKeys = this.getCachedAPIKeys(dealerId);
          if (apiKeys.openai) {
            openaiKey = apiKeys.openai;
            console.log(`?? Got OpenAI API key from dealer: ${dealerId}`);
          }
        } catch (error) {
          console.warn(`?? Could not get API keys from dealer ${dealerId}:`, error.message);
        }
      }
      
      // If no key from specified dealer, try to get from any available dealer
      if (!openaiKey) {
        console.log('?? No API key from specified dealer, trying to get from any available dealer...');
        openaiKey = await this.getAvailableOpenAIKey();
      }
      
      // CRITICAL: Never use environment variables - only use settings manager
      if (!openaiKey) {
        console.error(`? CRITICAL: OpenAI API key not found in settings manager for dealer: ${dealerId || 'global'}`);
        console.error(`? This will cause 500 errors in production!`);
        console.error(`? Settings manager available:`, !!this.settingsManager);
        this.crewAI = null;
        return;
      }

      // Initialize OpenAI LLM with configurable maxTokens
      this.crewAI = new ChatOpenAI({
        openAIApiKey: openaiKey,
        modelName: 'gpt-4o-mini',
        maxTokens: this.maxTokens,
        temperature: 0.7,
        streaming: false
      });
      
      // console.log(`? CrewAI LLM initialized for dealer: ${dealerId} with available API key`);
      
      // CRITICAL FIX: Initialize dealership agents after LLM is ready
      // console.log('?? Initializing dealership agents...');
      await this.initializeDealershipAgents(dealerId);
      // console.log('? Dealership agents initialized');
      
      // Initialize agent selector
      // console.log('?? Initializing AgentSelector...');
      this.agentSelector = new AgentSelector(openaiKey);
      // console.log('? Agent selector initialized');
      
      // Initialize intent training system
      try {
        // console.log('?? Initializing IntentTrainingSystem...');
        // console.log('?? IntentTrainingSystem constructor:', typeof IntentTrainingSystem);
        // console.log('?? IntentTrainingSystem import check:', IntentTrainingSystem);
        
        this.intentTrainingSystem = new IntentTrainingSystem(openaiKey);
        // console.log('? Intent training system initialized');
        // console.log('?? IntentTrainingSystem object:', typeof this.intentTrainingSystem);
        // console.log('?? IntentTrainingSystem methods:', Object.getOwnPropertyNames(this.intentTrainingSystem));
      } catch (intentError) {
        console.error('? Error initializing IntentTrainingSystem:', intentError);
        // console.error('? IntentTrainingSystem error details:', intentError.stack);
        this.intentTrainingSystem = null;
      }
      
    } catch (error) {
      console.error('? Error initializing CrewAI LLM:', error);
      this.crewAI = null;
    }
  }

  // NEW: Get API key dynamically from any available dealer
  async getAvailableOpenAIKey() {
    try {
      // Use centralized settings manager if available
      if (this.settingsManager) {
        try {
          // CRITICAL FIX: Try to get from any dealer first (prioritize dealer-specific keys)
          const availableKeys = await this.settingsManager.getAvailableAPIKeys();
          if (availableKeys.openai) {
            console.log('?? Found OpenAI API key from available dealer settings');
            return availableKeys.openai;
          }
          
          // Fallback to global settings if no dealer keys found
          const globalSettings = await this.settingsManager.getAllSettings();
          if (globalSettings.openai_key) {
            console.log('?? Found OpenAI API key from global settings (fallback)');
            return globalSettings.openai_key;
          }
        } catch (settingsError) {
          console.warn('?? Settings manager error:', settingsError.message);
        }
      }
      
      // CRITICAL: Never use environment variables - only use settings manager
      if (!this.settingsManager) {
        console.warn('?? Settings manager not available - cannot get OpenAI API key');
        return null;
      }
      
      console.error('? CRITICAL: No OpenAI API key found anywhere in settings manager!');
      console.error('? This will cause 500 errors in production!');
      return null;
    } catch (error) {
      console.error('? Error getting OpenAI API key:', error);
      return null;
    }
  }


