  calculateLeadScoreFromMessage(userMessage) {
    // CRITICAL FIX: Handle both string and object parameters
    let message = '';
    if (typeof userMessage === 'string') {
      message = userMessage;
    } else if (userMessage && typeof userMessage === 'object' && userMessage.message) {
      message = userMessage.message;
    } else {
      console.warn('?? Invalid userMessage format for calculateLeadScoreFromMessage:', userMessage);
      return 0;
    }
    
    // Simple lead scoring based on keywords
    message = message.toLowerCase();
    let score = 0;
    
    if (message.includes('buy') || message.includes('purchase')) score += 30;
    if (message.includes('price') || message.includes('cost')) score += 20;
    if (message.includes('test drive') || message.includes('schedule')) score += 25;
    if (message.includes('financing') || message.includes('loan')) score += 20;
    if (message.includes('urgent') || message.includes('asap')) score += 15;
    
    return Math.min(score, 100);
  }

  /**
   * Extract structured client preferences from a raw message and optional context.
   * Returns: { vehicleType, preferredModels, budgetRange, features, conditionPreference, colorPreference }
   */
  extractClientPreferences(message, context = {}) {
    try {
      const msgLower = (message || '').toLowerCase();
      const prefs = {
        vehicleType: null,
        preferredModels: [],
        budgetRange: null,
        features: [],
        conditionPreference: null,
        colorPreference: null
      };

      // --- Vehicle type ---
      if (msgLower.includes('suv') || msgLower.includes('crossover') || msgLower.includes('sport utility')) {
        prefs.vehicleType = 'suv';
      } else if (msgLower.includes('truck') || msgLower.includes('pickup')) {
        prefs.vehicleType = 'truck';
      } else if (msgLower.includes('sedan') || msgLower.includes('saloon')) {
        prefs.vehicleType = 'sedan';
      } else if (msgLower.includes('hatchback') || msgLower.includes('hatch')) {
        prefs.vehicleType = 'hatchback';
      }

      // --- Brand / model preferences ---
      const knownBrands = ['toyota', 'honda', 'ford', 'chevrolet', 'chevy', 'nissan', 'hyundai',
        'kia', 'bmw', 'mercedes', 'audi', 'lexus', 'acura', 'volkswagen', 'mazda', 'subaru',
        'jeep', 'dodge', 'buick', 'cadillac', 'lincoln', 'volvo', 'genesis'];
      knownBrands.forEach(b => { if (msgLower.includes(b)) prefs.preferredModels.push(b); });

      const knownModels = ['rav4', 'cr-v', 'tucson', 'escape', 'equinox', 'highlander', 'pilot',
        'atlas', 'explorer', 'traverse', 'pathfinder', 'murano', 'edge', 'blazer', 'santa fe',
        'palisade', 'kona', 'venue', 'sonata', 'camry', 'accord', 'civic', 'corolla', 'altima',
        'malibu', 'fusion', 'elantra', 'f-150', 'silverado', 'tacoma', 'tundra', 'ridgeline'];
      knownModels.forEach(m => { if (msgLower.includes(m)) prefs.preferredModels.push(m); });
      prefs.preferredModels = [...new Set(prefs.preferredModels)];

      // --- Budget ---
      const budgetPatterns = [
        /\$(\d{1,3}(?:,\d{3})*)/,
        /(\d{1,3}(?:,\d{3})*)\s*(?:dollars?|usd)/i,
        /budget\s*(?:is|of)?\s*\$?\s*(\d{1,3}(?:,\d{3})*)/i,
        /(?:range|limit)\s*(?:is|of|are)?\s*\$?\s*(\d{1,3}(?:,\d{3})*)/i,
        /(?:my|the)\s+(?:budget|range|limit)\s+(?:is|are|=)?\s*\$?\s*(\d{1,3}(?:,\d{3})*)/i,
        /(?:under|around|about|within)\s*\$?(\d{1,3}(?:,\d{3})*)/i,
        /\b(\d{2,3})k\b/i
      ];
      for (const pattern of budgetPatterns) {
        const m = msgLower.match(pattern);
        if (m) {
          let amount = parseFloat(m[1].replace(/,/g, ''));
          if (pattern.source.includes('k\\b')) amount *= 1000;
          const yr = new Date().getFullYear();
          if (amount >= 1000 && !(amount >= 2000 && amount <= yr + 2)) {
            prefs.budgetRange = {
              minBudget: Math.round(amount * 0.7),
              maxBudget: amount,
              preferredBudget: Math.round(amount * 0.9)
            };
            break;
          }
        }
      }

      // --- Color ---
      const colorMatch = msgLower.match(/\b(white|silver|black|red|blue|grey|gray|green|brown|gold|beige|pearl|navy|maroon|burgundy|orange|yellow|purple|pink|champagne|charcoal)\b/);
      if (colorMatch) {
        prefs.colorPreference = colorMatch[1];
        // Also set light/dark tone
        const lightColors = new Set(['white', 'silver', 'beige', 'champagne', 'pearl', 'gold', 'ivory']);
        const darkColors = new Set(['black', 'navy', 'charcoal', 'maroon', 'burgundy', 'dark gray', 'dark grey']);
        if (lightColors.has(colorMatch[1])) prefs.colorTone = 'light';
        else if (darkColors.has(colorMatch[1])) prefs.colorTone = 'dark';
        else prefs.colorTone = colorMatch[1];
      }

      // --- Features ---
      const featureKeywords = ['safety', 'leather', 'sunroof', 'moonroof', 'awd', 'all-wheel', '4wd',
        'bluetooth', 'navigation', 'carplay', 'android auto', 'backup camera', 'heated seats',
        'ventilated', 'panoramic', 'hybrid', 'electric', 'fuel efficient'];
      featureKeywords.forEach(f => { if (msgLower.includes(f)) prefs.features.push(f); });

      // --- Condition ---
      if (msgLower.includes('new car') || msgLower.includes('brand new') || msgLower.match(/\bnew\b/)) {
        prefs.conditionPreference = 'new';
      } else if (msgLower.includes('used') || msgLower.includes('pre-owned') || msgLower.includes('preowned') || msgLower.includes('second hand')) {
        prefs.conditionPreference = 'used';
      } else if (msgLower.includes('certified') || msgLower.includes('cpo') || msgLower.includes('like-new') || msgLower.includes('like new')) {
        prefs.conditionPreference = 'like-new';
      }

      // Enrich from conversation context if available
      const ctxPrefs = context?.Daivesteps?.[3]?.slots?.customerPreferences || {};
      if (!prefs.vehicleType && ctxPrefs.preferred_type?.[0]) prefs.vehicleType = ctxPrefs.preferred_type[0];
      if (!prefs.budgetRange) {
        const ctxBudget = context?.Daivesteps?.[2]?.slots?.budget || context?.Daivesteps?.[2]?.budget;
        // Accept either max_price or target_price as the budget ceiling
        const budgetCap = ctxBudget?.max_price || ctxBudget?.target_price;
        if (budgetCap) {
          prefs.budgetRange = {
            minBudget: Math.round(budgetCap * 0.7),
            maxBudget: budgetCap,
            preferredBudget: Math.round(budgetCap * 0.9)
          };
        }
      }

      return prefs;
    } catch (err) {
      console.warn('?? extractClientPreferences error:', err.message);
      return { vehicleType: null, preferredModels: [], budgetRange: null, features: [], conditionPreference: null, colorPreference: null };
    }
  }

