/**
 * ? NEW: Enhanced method to update daivestep fields with automatic completion tracking
 */
DAIVEService.prototype.updateDaivestepsField = function(conversationContext, stepKey, fieldPath, value) {
  try {
    // Use the base methods directly
    this.updateDaivestepsField(conversationContext, stepKey, fieldPath, value);
    this.checkAndUpdateStepCompletion(conversationContext, stepKey);
  } catch (error) {
    console.error('? Error updating Daivesteps field with tracking:', error);
  }
};

/**
 * ? NEW: Comprehensive step completion tracking and progression system
 */
DAIVEService.prototype.trackStepCompletion = function(conversationContext, stepKey, fieldPath, value) {
  try {
    console.log(`?? Tracking step completion for: ${stepKey} - ${fieldPath} = ${value}`);
    
    // Update the field
    this.updateDaivestepsField(conversationContext, stepKey, fieldPath, value);
    
    // Check if this update triggers step completion
    const stepNumber = this.extractStepNumber(stepKey);
    if (stepNumber) {
      const stepName = this.getStepNameFromNumber(stepNumber);
      if (stepName) {
        const isCompleted = this.isStepCompletedEnhanced(stepName, conversationContext);
        
        if (isCompleted) {
          console.log(`? Step ${stepName} completed after updating ${fieldPath}`);
          
          // Mark as completed in daivestep array
          if (conversationContext.Daivesteps[stepKey]) {
            conversationContext.Daivesteps[stepKey].status = 'Completed';
            conversationContext.Daivesteps[stepKey].completed_at = new Date().toISOString();
          }
          
          // Update stepCompleted tracking
          if (conversationContext.stepCompleted) {
            conversationContext.stepCompleted[stepName] = true;
            conversationContext.last_updated = new Date().toISOString();
          }
          
          // Auto-advance to next step
          this.autoAdvanceToNextStep(conversationContext, stepName);
          
          // Log completion status (simplified)
          console.log(`? Step ${stepName} completed and logged`);
        }
      }
    }
  } catch (error) {
    console.error('? Error tracking step completion:', error);
  }
};

/**
 * ? NEW: Extract step number from stepKey
 */
DAIVEService.prototype.extractStepNumber = function(stepKey) {
  // Handle both "Step X" format and numeric format
  const stepMatch = stepKey.match(/Step (\d+)/);
  if (stepMatch) {
    return parseInt(stepMatch[1]);
  }
  
  // Handle numeric step keys like "1", "2", "3"
  const numericMatch = stepKey.match(/^(\d+)$/);
  if (numericMatch) {
    return parseInt(numericMatch[1]);
  }
  
  return null;
};

/**
 * ? NEW: Get step name from step number
 */
DAIVEService.prototype.getStepNameFromNumber = function(stepNumber) {
  const stepMapping = {
    1: 'inquiry',
    2: 'lead_capture', 
    3: 'vehicle_selection',
    4: 'test_drive',
    5: 'trade_evaluation',
    6: 'qualification',
    7: 'purchase_commitment',
    8: 'vehicle_prep',
    9: 'finance_manager',
    10: 'delivery',
    11: 'csi_followup'
  };
  return stepMapping[stepNumber];
};

/**
 * ? NEW: Enhanced step completion validation with specific field checks
 */
DAIVEService.prototype.isStepCompletedEnhanced = function(stepName, conversationContext) {
  const stepData = this.getStepData(stepName, conversationContext);
  if (!stepData) return false;

  // Step-specific completion logic
  switch (stepName) {
    case 'inquiry':
      return this.isInquiryStepCompleted(stepData, conversationContext);
    
    case 'lead_capture':
      return this.isLeadCaptureStepCompleted(stepData, conversationContext);
    
    case 'vehicle_selection':
      return this.isVehicleSelectionStepCompleted(stepData, conversationContext);
    
    case 'test_drive':
      return this.isTestDriveStepCompleted(stepData, conversationContext);
    
    case 'trade_evaluation':
      return this.isTradeEvaluationStepCompleted(stepData, conversationContext);
    
    case 'qualification':
      return this.isQualificationStepCompleted(stepData, conversationContext);
    
    case 'purchase_commitment':
      return this.isPurchaseCommitmentStepCompleted(stepData, conversationContext);
    
    default:
      // Fallback to original logic
      return this.isStepCompleted(stepName, conversationContext);
  }
};

/**
 * ? NEW: Check if inquiry step is completed
 */
DAIVEService.prototype.isInquiryStepCompleted = function(stepData, conversationContext) {
  // ?? UPDATED: Only require vehicle_type as per new mandatory slots configuration
  const hasVehicleType = stepData?.vehicle_type || 
                        stepData?.slots?.vehicle_type ||
                        stepData?.slots?.VehicleSelection?.type;
  
  return !!hasVehicleType;
};

/**
 * ? NEW: Check if lead capture step is completed
 */
DAIVEService.prototype.isLeadCaptureStepCompleted = function(stepData, conversationContext) {
  // ?? UPDATED: Only require budget as per new mandatory slots configuration
  const hasBudget = stepData?.budget?.target_price || 
                   stepData?.budget?.max_price ||
                   stepData?.budget?.has_budget ||
                   stepData?.slots?.budget?.target_price ||
                   stepData?.slots?.budget?.max_price ||
                   stepData?.slots?.budget?.has_budget;
  
  return !!hasBudget;
};

/**
 * ? NEW: Check if vehicle selection step is completed
 */
DAIVEService.prototype.isVehicleSelectionStepCompleted = function(stepData, conversationContext) {
  // ?? UPDATED: Only require vehicle_selected as per new mandatory slots configuration
  const hasSelection = stepData?.slots?.inventory_choice ||
                      stepData?.slots?.selectedVehicle ||
                      stepData?.slots?.VehicleSelection?.selectedVehicle ||
                      stepData?.slots?.vehicle_selected;
  
  return !!hasSelection;
};

/**
 * ? NEW: Check if test drive step is completed
 */
DAIVEService.prototype.isTestDriveStepCompleted = function(stepData, conversationContext) {
  // Check for test drive confirmation or completion
  const hasConfirmation = stepData?.test_drive?.hasConfirmedInterest ||
                         stepData?.test_drive?.isScheduled ||
                         stepData?.test_drive?.completion_status === 'completed';
  
  const hasCompletion = stepData?.test_drive?.step === 'completed' ||
                       stepData?.test_drive?.deal_ready === true;
  
  return !!(hasConfirmation || hasCompletion);
};

/**
 * ? NEW: Check if trade evaluation step is completed
 */
DAIVEService.prototype.isTradeEvaluationStepCompleted = function(stepData, conversationContext) {
  // Check if trade-in was declined (step completed)
  if (stepData?.trade_in?.declined === true || stepData?.trade_in?.intent === false) {
    return true;
  }
  // Flat slot: trade_in_declined set by handler
  if (stepData?.slots?.trade_in_declined === true) {
    return true;
  }
  
  // Check if trade-in details were provided (step completed)
  if (stepData?.trade_in?.details_provided === true && stepData?.trade_in?.vehicle_info) {
    return true;
  }
  
  // Check for trade-in vehicle information in slots
  const hasTradeVehicle = stepData?.slots?.trade_in_vehicle ||
                         stepData?.slots?.trade_in_details ||
                         stepData?.trade_in?.vehicle_info;
  if (hasTradeVehicle) return true;

  // Flat slots written by NLP (trade_in_make + trade_in_model = enough to consider stage entered)
  const hasTradeFlat = stepData?.slots?.trade_in_make && stepData?.slots?.trade_in_model;
  if (hasTradeFlat) return true;

  // status/stageCompleted flags
  if (stepData?.status === 'completed' || stepData?.stageCompleted === true) return true;

  return false;
};

/**
 * ? NEW: Check if qualification step is completed
 */
DAIVEService.prototype.isQualificationStepCompleted = function(stepData, conversationContext) {
  // Check if financing method is selected (cash, finance, or lease) or down payment provided
  if (stepData?.finance?.preferred_method || stepData?.finance?.mode || 
      stepData?.slots?.finance?.preferred_method || 
      stepData?.slots?.finance?.down_payment || stepData?.slots?.finance?.down_payment_provided) {
    return true;
  }
  
  // Check for qualification information (including credit_identified)
  const hasQualification = stepData?.slots?.qualification ||
                          stepData?.qualification?.credit_situation ||
                          stepData?.slots?.qualification?.credit_identified === true ||
                          stepData?.slots?.qualification?.credit_score ||
                          stepData?.qualification?.employment_status ||
                          stepData?.qualification?.financing_method;
  
  return !!hasQualification;
};

/**
 * ? NEW: Check if purchase commitment step is completed
 */
DAIVEService.prototype.isPurchaseCommitmentStepCompleted = function(stepData, conversationContext) {
  // Check if purchase decision is made (yes or no)
  if (stepData?.purchase?.decision === 'yes' || stepData?.purchase?.committed === true) {
    return true;
  }
  
  // Check for purchase timeline or commitment
  const hasTimeline = stepData?.slots?.purchase_timeline ||
                     stepData?.purchase_commitment?.timeline ||
                     stepData?.purchase?.timeline;
  
  const hasCommitment = stepData?.purchase_commitment?.isCommitted ||
                       stepData?.slots?.purchase_commitment ||
                       stepData?.purchase?.ready_to_buy;
  
  return !!(hasTimeline || hasCommitment);
};

/**
 * ? NEW: Get step data from conversation context
 */
DAIVEService.prototype.getStepData = function(stepName, conversationContext) {
  const stepNumber = this.getStepNumber(stepName);
  // Try both numeric key and full step key
  return conversationContext.Daivesteps?.[stepNumber] || 
         conversationContext.Daivesteps?.[`Step ${stepNumber} - ${this.getStepDisplayName(stepName)}`];
};

/**
 * REMOVED: Duplicate getStepNumber and getStepDisplayName methods - using the ones in JourneyCompletionManager class
 */

/**
 * ? NEW: Auto-advance to next step when current step is completed
 */
DAIVEService.prototype.autoAdvanceToNextStep = function(conversationContext, completedStepName) {
  try {
    const currentStep = conversationContext.currentJourneyStep;
    
    // Only advance if the completed step is the current step
    if (currentStep === completedStepName) {
      const nextStep = this.getNextIncompleteStep(conversationContext);
      if (nextStep && nextStep !== currentStep) {
        conversationContext.currentJourneyStep = nextStep;
        conversationContext.Currentstep = this.getStepDisplayName(nextStep);
        console.log(`?? Auto-advanced to next step: ${currentStep} ? ${nextStep}`);
      }
    }
  } catch (error) {
    console.error('? Error auto-advancing to next step:', error);
  }
};

/**
 * ? NEW: Get next incomplete step
 */
DAIVEService.prototype.getNextIncompleteStep = function(conversationContext) {
  const steps = ['inquiry', 'lead_capture', 'vehicle_selection', 'test_drive', 'trade_evaluation', 'qualification', 'purchase_commitment', 'vehicle_prep', 'finance_manager', 'delivery', 'csi_followup'];
  
  for (const step of steps) {
    if (!conversationContext.stepCompleted?.[step]) {
      return step;
    }
  }
  return null; // All steps completed
};

/**
 * ? NEW: Log current step completion status
 */
DAIVEService.prototype.logStepCompletionStatus = function(conversationContext) {
  try {
    console.log('\n?? === STEP COMPLETION STATUS ===');
    
    // Log daivestep array status
    Object.keys(conversationContext.Daivesteps || {}).forEach(stepKey => {
      const step = conversationContext.Daivesteps[stepKey];
      const status = step?.status || 'Pending';
      const completedAt = step?.completed_at || 'N/A';
      console.log(`  ${stepKey}: ${status} (${completedAt})`);
    });
    
    // Log stepCompleted tracking
    if (conversationContext.stepCompleted) {
      console.log('\n?? Step Completed Tracking:');
      Object.keys(conversationContext.stepCompleted).forEach(step => {
        const completed = conversationContext.stepCompleted[step];
        console.log(`  ${step}: ${completed ? '? Completed' : '? Pending'}`);
      });
    }
    
    console.log(`\n?? Current Journey Step: ${conversationContext.currentJourneyStep || 'Not set'}`);
    console.log('=====================================\n');
  } catch (error) {
    console.error('? Error logging step completion status:', error);
  }
};

/**
 * ? NEW: Method to get current step completion summary
 */
DAIVEService.prototype.getStepCompletionSummary = function(conversationContext) {
  try {
    const summary = {
      currentStep: conversationContext.currentJourneyStep || 'Not set',
      completedSteps: [],
      pendingSteps: [],
      daivestepStatus: {},
      stepCompletedStatus: {}
    };
    
    // Check daivestep array status
    Object.keys(conversationContext.Daivesteps || {}).forEach(stepKey => {
      const step = conversationContext.Daivesteps[stepKey];
      const status = step?.status || 'Pending';
      summary.daivestepStatus[stepKey] = status;
      
      if (status === 'Completed') {
        summary.completedSteps.push(stepKey);
      } else {
        summary.pendingSteps.push(stepKey);
      }
    });
    
    // Check stepCompleted tracking
    if (conversationContext.stepCompleted) {
      Object.keys(conversationContext.stepCompleted).forEach(step => {
        summary.stepCompletedStatus[step] = conversationContext.stepCompleted[step];
      });
    }
    
    return summary;
  } catch (error) {
    console.error('? Error getting step completion summary:', error);
    return null;
  }
};

