// ? NEW: Centralized Stage Advancement Function
function getNextStage(currentStage, slots, conversationContext = {}) {
  // console.log(`?? Centralized stage advancement: ${currentStage} ? ?`);
  
  // Validate test drive completion before any advancement
  if (!validateTestDriveCompletion(slots, conversationContext)) {
    return currentStage;
  }
  
  // Use the existing advanceStage function as the single source of truth
  const nextStage = advanceStage(currentStage, slots, conversationContext);
  
  console.log(`? Stage advancement: ${currentStage} ? ${nextStage}`);
  return nextStage;
}

// ? NEW: Helper function to extract stock number from inventory data
function extractStockNumber(vehicle) {
  // First try to get stock_number field directly
  if (vehicle.stock_number) {
    return vehicle.stock_number;
  }
  
  // Fallback to extracting from location field
  if (vehicle.location) {
    const match = vehicle.location.match(/Stock\s*#\s*([A-Z0-9]+)/i);
    return match ? match[1] : vehicle.location;
  }
  
  return 'N/A';
}

// ? NEW: Vehicle Rejection Detection and Handling
function detectVehicleRejection(userMessage) {
  const messageLower = userMessage.toLowerCase();
  
  // First check for positive responses that should NOT be treated as rejection
  const positivePatterns = [
    /yes.*for.*opt/i,           // "yes for option 2"
    /yes.*for.*option/i,        // "yes for option 1"
    /yes.*for.*veh/i,           // "yes for vehicle"
    /yes.*for.*no\s*\d/i,       // "yes for no 2" (typo)
    /yes.*for.*\d/i,            // "yes for 2"
    /option\s*\d/i,             // "option 2"
    /opt\s*\d/i,                // "opt 2"
    /yes.*\d/i,                 // "yes 2"
    /yes.*test/i,               // "yes test drive"
    /yes.*drive/i,              // "yes drive"
    /yes.*interested/i,         // "yes interested"
    /yes.*like/i,               // "yes like"
    /yes.*want/i,               // "yes want"
    /yes.*sure/i,               // "yes sure"
    /yes.*ok/i,                 // "yes ok"
    /yes.*proceed/i,            // "yes proceed"
    /yes.*confirm/i,            // "yes confirm"
    /yes.*agree/i,              // "yes agree"
    // ? NEW: Test drive progression patterns
    /whats.*next.*process/i,    // "whats the next process"
    /what.*next.*process/i,      // "what is the next process"
    /next.*process/i,           // "next process"
    /whats.*next/i,             // "whats next"
    /what.*next/i,              // "what is next"
    /next.*step/i,              // "next step"
    /whats.*next.*step/i,       // "whats next step"
    /what.*next.*step/i,        // "what is next step"
    /drive.*was.*great/i,       // "drive was great"
    /glad.*drive.*was.*great/i, // "glad drive was great"
    /i.*am.*glad.*drive/i,      // "i am glad drive was great"
    /its.*was.*great.*drive/i,  // "its was great drive"
    /it.*was.*great.*drive/i,   // "it was great drive"
    /the.*drive.*was.*great/i,  // "the drive was great"
    /test.*drive.*done/i,       // "test drive done"
    /finished.*test.*drive/i,   // "finished test drive"
    /test.*drove.*it/i,         // "test drove it"
    /drove.*it/i,               // "drove it"
    // ? Scheduling / day-selection phrases ? never a vehicle rejection
    /another\s*day/i,           // "another day"
    /^anotherday$/i,            // "anotherday" (typo)
    /different\s*day/i,         // "different day"
    /some\s*other\s*(day|time)/i, // "some other day/time"
    /not\s*today/i,             // "not today"
    /schedule/i,                // "schedule"
    /next\s*week/i,             // "next week"
    /tomorrow/i,                // "tomorrow"
    /weekend/i                  // "weekend"
  ];
  
  // If it matches positive patterns, it's NOT a rejection
  if (positivePatterns.some(pattern => pattern.test(userMessage))) {
    return false;
  }
  
  // Now check for actual rejection keywords
  const rejectionKeywords = [
    'not interested', 'don\'t like', 'don\'t want', 'reject', 'pass',
    'not for me', 'not what i want', 'not suitable', 'not right', 'wrong',
    'something else', 'next option', 'skip', 'no thanks'
    // Removed: 'different', 'another', 'next' ? too broad; match 'another day' as scheduling above
  ];
  
  // Only check for rejection if it's not a positive response
  // ? ENHANCED: Handle "pass" ambiguity - "pass" can mean "reject" OR "great/excellent"
  if (/\bpass\b/i.test(messageLower)) {
    // Check if "pass" is used in a positive context
    const positiveContextWithPass = [
      /pass.*great/i,
      /pass.*good/i,
      /pass.*fine/i,
      /pass.*excellent/i,
      /pass.*amazing/i,
      /pass.*awesome/i,
      /pass.*wonderful/i,
      /pass.*love/i,
      /glad.*pass/i,
      /happy.*pass/i,
      /pleased.*pass/i,
      /pass.*positive/i
    ];
    
    // If "pass" has positive context, it's NOT a rejection
    if (positiveContextWithPass.some(pattern => pattern.test(userMessage))) {
      return false;
    }
    
    // Otherwise, "pass" is a rejection (passing on something)
    return true;
  }
  
  return rejectionKeywords.some(keyword => messageLower.includes(keyword));
}

// ? NEW: Handle Vehicle Rejection
function handleVehicleRejection(conversationContext) {
  if (conversationContext.currentVehicle) {
    // Add to rejected vehicles
    this.getVehicleArrays(conversationContext).rejectedVehicles.push(conversationContext.currentVehicle);
    console.log(`? Vehicle rejected: ${conversationContext.currentVehicle.make} ${conversationContext.currentVehicle.model}`);
    
    // Clear current vehicle
    conversationContext.currentVehicle = null;
    
    // Reset relevant slots using Daivesteps structure
    if (conversationContext.Daivesteps[3]?.slots) {
      conversationContext.Daivesteps[3].slots.VehicleSelection.model = null;
      conversationContext.Daivesteps[3].slots.VehicleSelection.trim = null;
      conversationContext.Daivesteps[3].slots.inventory_choice = null;
      conversationContext.Daivesteps[3].slots.vehicleHistory.current_vehicle = null;
    }
  }
}

// ? NEW: Suggest Next Vehicle After Rejection
function suggestNextVehicle(conversationContext, inventoryList) {
  if (!inventoryList || inventoryList.length === 0) {
    return null;
  }
  
  const rejectedIds = this.getVehicleArrays(conversationContext).rejectedVehicles.map(v => v.id || v.stock_number);
  const preferences = conversationContext.vehicle || this.getPreferences(conversationContext);
  
  // Find next vehicle that matches preferences but hasn't been rejected
  const nextVehicle = inventoryList.find(vehicle => {
    const matchesPreferences = (
      (!preferences.make || vehicle.make?.toLowerCase() === preferences.make?.toLowerCase()) &&
      (!preferences.type || vehicle.type?.toLowerCase() === preferences.type?.toLowerCase()) &&
      (!preferences.budget?.max_price || vehicle.price <= preferences.budget.max_price)
    );
    
    const notRejected = !rejectedIds.includes(vehicle.id );
    
    return matchesPreferences && notRejected;
  });
  
  if (nextVehicle) {
    conversationContext.currentVehicle = nextVehicle;
    conversationContext.shortlistedVehicles.push(nextVehicle);
    console.log(`? Suggested next vehicle: ${nextVehicle.make} ${nextVehicle.model}`);
  }
  
  return nextVehicle;
}

// ? NEW: Detect Vague Affirmations (more specific to avoid false positives)
function detectVagueAffirmation(userMessage) {
  const messageLower = userMessage.toLowerCase();
  
  // Only detect as affirmation if it's a short response to a specific question
  const affirmationKeywords = [
    'yes', 'sure', 'go ahead', 'okay', 'ok', 'i agree', 'sounds good',
    'that works', 'perfect', 'great', 'fine', 'alright', 'proceed'
  ];
  
  // Check if message is short and contains affirmation keywords
  const isShortResponse = messageLower.split(' ').length <= 3;
  const hasAffirmationKeyword = affirmationKeywords.some(keyword => messageLower.includes(keyword));
  
  // Only return true if it's a short response with affirmation keywords
  // This prevents "I am looking for suv" from being detected as affirmation
  return isShortResponse && hasAffirmationKeyword;
}

// ? NEW: Enhanced Intent Memory Stack System
function handleVagueAffirmation(conversationContext, userMessage) {
  // 1. Check for lastPromptedIntent (highest priority)
  if (conversationContext.lastPromptedIntent) {
    console.log(`? Vague affirmation mapped to lastPromptedIntent: ${conversationContext.lastPromptedIntent}`);
    return conversationContext.lastPromptedIntent;
  }
  
  // 2. Check intentQueue for most recent unfulfilled intent
  if (conversationContext.intentQueue && conversationContext.intentQueue.length > 0) {
    const mostRecentIntent = conversationContext.intentQueue[conversationContext.intentQueue.length - 1];
    console.log(`? Vague affirmation mapped to most recent intent: ${mostRecentIntent.intent}`);
    return mostRecentIntent.intent;
  }
  
  
  return 'affirmation'; // Default fallback
}

// ? NEW: Store Intent in Memory Stack
function storePromptedIntent(conversationContext, intent, question = null) {
  if (!conversationContext.lastPromptedIntent) {
    conversationContext.lastPromptedIntent = null;
  }
  if (!conversationContext.intentQueue) {
    conversationContext.intentQueue = [];
  }
  
  // Store in lastPromptedIntent
  conversationContext.lastPromptedIntent = intent;
  
  // Add to intentQueue with timestamp
  conversationContext.intentQueue.push({
    intent: intent,
    timestamp: new Date().toISOString(),
    question: question
  });
  
  // Keep only last 5 intents to prevent memory bloat
  if (conversationContext.intentQueue.length > 5) {
    conversationContext.intentQueue = conversationContext.intentQueue.slice(-5);
  }
  
  console.log(`?? Stored prompted intent: ${intent}`);
}

// ? NEW: Clear Intent from Memory Stack
function clearPromptedIntent(conversationContext, intent = null) {
  if (intent) {
    // Clear specific intent
    conversationContext.intentQueue = conversationContext.intentQueue.filter(item => item.intent !== intent);
    if (conversationContext.lastPromptedIntent === intent) {
      conversationContext.lastPromptedIntent = conversationContext.intentQueue.length > 0 
        ? conversationContext.intentQueue[conversationContext.intentQueue.length - 1].intent 
        : null;
    }
    console.log(`??? Cleared specific intent: ${intent}`);
  } else {
    // Clear all
    conversationContext.lastPromptedIntent = null;
    conversationContext.intentQueue = [];
    console.log(`??? Cleared all intents from memory stack`);
  }
}

// Helper function to update both stage and journey step
function updateStage(slots, newStage, conversationContext = null) {
  // Validate test drive completion before allowing stage advancement
  if (!validateTestDriveCompletion(slots, conversationContext)) {
    console.log('? Stage advancement blocked - test drive not completed');
    return false;
  }
  
  slots.stage = newStage;
  
  // Also update conversation context if provided
  if (conversationContext) {
    conversationContext.stage = newStage;
  }
  
  console.log(`?? Stage updated to ${newStage}`);
  return true;
}

function advanceStage(currentStage, slots, conversationContext = null) {
  const currentIndex = STAGES.indexOf(currentStage);
  if (currentIndex === -1) return 'inquiry';
  
  // Step 1 (Inquiry) ? Step 2 (Lead Capture): When vehicle interest is expressed
  if (currentStage === 'inquiry' && (slots.vehicle_type )) {
    console.log('?? Vehicle interest expressed - advancing to lead capture');
    return 'lead_capture';
  }
  
  // Step 2 (Lead Capture) ? Step 3 (Vehicle Selection): When vehicle preferences are collected
  if (currentStage === 'lead_capture' && (slots.make || slots.model || slots.budget?.target_price || slots.budget?.max_price || slots.vehicle_type)) {
    console.log('?? Lead captured with vehicle preferences - advancing to vehicle selection');
    return 'vehicle_selection';
  }
  
  // Step 3 (Vehicle Selection) ? Step 4 (Test Drive): When vehicle preferences are expressed
  if (currentStage === 'vehicle_selection' && (slots.inventory_choice || slots.selected_vehicle || slots.make || slots.model)) {
    console.log('?? Vehicle preferences expressed - advancing to test drive');
    return 'test_drive';
  }
  
  // Step 4 (Test Drive) ? Step 5 (Trade Evaluation): When test drive is completed or customer expresses satisfaction
  if (currentStage === 'test_drive') {
    // ? FIXED: Use the same logic as validateTestDriveCompletion
    let testDriveCompleted = false;
    
    // First try to get data from conversation context if available
    if (conversationContext && conversationContext.Daivesteps?.[4]) {
      const step4 = conversationContext.Daivesteps[4];
      testDriveCompleted = 
        step4.stageCompleted === true ||
        step4.slots?.slotDetectionStatus === 'complete' ||
        (step4.slots?.test_drive_completed === true && step4.slots?.test_drive_review) ||
        step4.slots?.completion_status === 'completed';
    }
    
    // Fallback to checking slots object directly
    if (!testDriveCompleted) {
      testDriveCompleted = 
        slots.test_drive_scheduled === true ||
        slots.test_drive?.completion_status === 'completed' || 
        slots.test_drive?.step === 'completed' ||
        slots.test_drive?.deal_ready === true ||
        slots.test_drive?.step === 'review_collected' ||
        slots.test_drive?.hasConfirmedInterest === true ||
        slots.test_drive?.isScheduled === true;
    }
    
    console.log('?? Test drive step progression check:', {
      currentStage: currentStage,
      hasConversationContext: !!conversationContext,
      step4StageCompleted: conversationContext?.Daivesteps?.[4]?.stageCompleted,
      step4SlotStatus: conversationContext?.Daivesteps?.[4]?.slots?.slotDetectionStatus,
      step4TestDriveCompleted: conversationContext?.Daivesteps?.[4]?.slots?.test_drive_completed,
      step4TestDriveReview: conversationContext?.Daivesteps?.[4]?.slots?.test_drive_review,
      slotsTestDriveScheduled: slots.test_drive_scheduled,
      slotsCompletionStatus: slots.test_drive?.completion_status,
      slotsStep: slots.test_drive?.step,
      slotsDealReady: slots.test_drive?.deal_ready,
      slotsHasConfirmedInterest: slots.test_drive?.hasConfirmedInterest,
      slotsIsScheduled: slots.test_drive?.isScheduled,
      testDriveCompleted: testDriveCompleted
    });
    
    if (testDriveCompleted) {
      // Guard: do NOT advance while the negative-feedback concern/inventory flow is still running.
      // awaiting_concern_detail = we asked "what didn't feel right?" and are waiting for the answer.
      // awaiting_inventory_confirmation = we offered alternatives and are waiting for yes/no.
      // Also block advancement when test_drive_review is not yet set ? review must be collected first.
      const _s4Slots = conversationContext?.Daivesteps?.[4]?.slots || {};
      const _review = _s4Slots.test_drive_review;
      const _awaitingConcern = _s4Slots.awaiting_concern_detail;
      const _awaitingInv = _s4Slots.awaiting_inventory_confirmation;
      if (!_review) {
        console.log('?? Test drive physically done but review not yet collected ? staying in test_drive');
        return 'test_drive';
      }
      if (_review === 'negative' && (_awaitingConcern || _awaitingInv)) {
        console.log('?? Test drive negative ? concern/inventory confirmation still pending ? staying in test_drive');
        return 'test_drive';
      }
      console.log('?? Test drive completed - advancing to trade evaluation');
      return 'trade_evaluation';
    }
    console.log('?? Test drive not completed - staying in test_drive');
    return 'test_drive';
  }
  
  // Step 5 (Trade Evaluation) ? Step 6 (Qualification): When trade evaluation is completed
  if (currentStage === 'trade_evaluation') {
    // Check from Daivesteps[5] slots (actual structure used by system)
    const step5Slots = conversationContext?.Daivesteps?.[5]?.slots || {};
    
    // If user declined trade-in, advance to qualification
    if (step5Slots.trade_in_declined === true || slots.trade_in?.inquiry === false || slots.trade_in?.intent === false) {
      console.log('?? Trade-in declined - advancing to qualification');
      return 'qualification';
    }
    
    // If user confirmed trade-in and provided details, advance to qualification
    const hasTradeInConfirmed = step5Slots.trade_in_confirmed === true || slots.trade_in?.inquiry === true;
    const hasTradeInDetails = step5Slots.trade_in_details || step5Slots.trade_in_make || slots.trade_in?.details_provided;
    const isEvaluated = step5Slots.trade_in_evaluated === true;
    
    console.log('?? Trade evaluation progression check:', {
      currentStage,
      hasTradeInConfirmed,
      hasTradeInDetails,
      isEvaluated,
      step5Status: conversationContext?.Daivesteps?.[5]?.status,
      step5StageCompleted: conversationContext?.Daivesteps?.[5]?.stageCompleted
    });
    
    if (hasTradeInConfirmed && hasTradeInDetails) {
      console.log('?? Trade-in details provided - advancing to qualification');
      return 'qualification';
    }
    
    // If user confirmed trade-in but hasn't provided details yet, stay in trade evaluation
    if (hasTradeInConfirmed && !hasTradeInDetails) {
      console.log('?? Trade-in confirmed but details not provided yet - staying in trade evaluation');
      return 'trade_evaluation';
    }
    
    // If no trade-in inquiry has been made yet, stay in trade evaluation
    return 'trade_evaluation';
  }
  
  // Step 6 (Qualification) ? Step 7 (Purchase Commitment): When financing details are discussed
  if (currentStage === 'qualification') {
    // Check from Daivesteps[6] slots (actual structure used by system)
    const step6Slots = conversationContext?.Daivesteps?.[6]?.slots || {};
    
    // Check if financing method is selected (or inferred from down payment)
    const hasExplicitFinanceMethod = step6Slots.finance?.preferred_method || slots.finance?.preferred_method;
    const hasDownPayment = step6Slots.finance?.down_payment || step6Slots.finance?.down_payment_provided;
    const hasFinanceMethod = hasExplicitFinanceMethod || (hasDownPayment && 'finance'); // Infer financing if down payment provided
    
    // Check if credit/qualification info is provided
    const hasCreditInfo = step6Slots.qualification?.credit_identified === true || 
                          step6Slots.qualification?.credit_score || 
                          step6Slots.qualification?.credit_situation ||
                          slots.qualification?.credit_situation;
    
    console.log('?? Qualification progression check:', {
      currentStage,
      hasExplicitFinanceMethod,
      hasDownPayment,
      hasFinanceMethod,
      hasCreditInfo,
      step6Status: conversationContext?.Daivesteps?.[6]?.status,
      step6StageCompleted: conversationContext?.Daivesteps?.[6]?.stageCompleted
    });
    
    // If financing method is selected and basic qualification is done, advance
    // BUT only after the credit application has actually been created and sent ?
    // collecting credit info means qualification is IN PROGRESS, not complete.
    if (hasFinanceMethod && hasCreditInfo) {
      const appCreated = conversationContext?.Daivesteps?.[6]?.slots?.application?.created === true;
      if (!appCreated) {
        console.log('? Qualification has credit info but application not yet created ? staying in qualification');
        return 'qualification';
      }
      console.log('?? Qualification completed - advancing to purchase commitment');
      return 'purchase_commitment';
    }
    
    // If user declined financing (cash payment), advance to purchase commitment
    if (step6Slots.finance?.mode === 'cash' || slots.finance?.mode === 'cash' || 
        step6Slots.finance?.preferred_method === 'cash' || slots.finance?.preferred_method === 'cash') {
      console.log('?? Cash payment selected - advancing to purchase commitment');
      return 'purchase_commitment';
    }
    
    return 'qualification';
  }
  
  // Step 7 (Purchase Commitment) ? Step 8 (Vehicle Prep): When commitment is secured
  if (currentStage === 'purchase_commitment') {
    // If user confirms purchase decision, advance to vehicle prep
    if (slots.purchase?.committed || slots.purchase?.decision === 'yes' || slots.purchase?.ready_to_buy) {
      console.log('?? Purchase commitment secured - advancing to vehicle prep');
      return 'vehicle_prep';
    }
    
    // If user declines purchase, stay in purchase commitment for negotiation
    if (slots.purchase?.decision === 'no' || slots.purchase?.declined) {
      console.log('?? Purchase declined - staying in purchase commitment for negotiation');
      return 'purchase_commitment';
    }
    
    return 'purchase_commitment';
  }
  
  // Step 8 (Vehicle Prep) ? Step 9 (Finance Manager): When vehicle preparation is complete
  if (currentStage === 'vehicle_prep' && slots.vehicle_prep?.completed) {
    console.log('?? Vehicle preparation completed - advancing to finance manager');
    return 'finance_manager';
  }
  
  // Step 9 (Finance Manager) ? Step 10 (Delivery): When financing paperwork is complete
  if (currentStage === 'finance_manager' && slots.finance?.paperwork_completed) {
    console.log('?? Finance paperwork completed - advancing to delivery');
    return 'delivery';
  }
  
  // Step 10 (Delivery) ? Step 11 (CSI & Follow-ups): When delivery is complete
  if (currentStage === 'delivery' && slots.delivery?.completed) {
    console.log('?? Delivery completed - advancing to CSI & follow-ups');
    return 'csi_followup';
  }
  
  // Step 11 (CSI & Follow-ups) - Final stage
  if (currentStage === 'csi_followup') {
    return 'csi_followup';
  }
  
  // Default progression to next stage
  return STAGES[Math.min(currentIndex + 1, STAGES.length - 1)];
}

// NEW: Check if budget mention is explicit (customer intentionally changing budget)
function isExplicitBudgetMention(newData, currentSlots, userMessage = '') {
  const messageLower = (userMessage || '').toLowerCase();
  
  // Budget keywords that indicate explicit budget mention
  const budgetKeywords = [
    'budget', 'price', 'cost', 'afford', 'spend', 'max', 'under', 'around', 'about',
    'dollar', 'dollars', 'thousand', 'k', 'budget range', 'price range', 'cost range',
    'my budget', 'budget is', 'price is', 'cost is', 'afford', 'can afford', 'spending',
    'maximum', 'up to', 'less than', 'more than', 'between', 'from', 'to'
  ];
  
  // Check if message contains explicit budget keywords
  const hasBudgetKeywords = budgetKeywords.some(keyword => messageLower.includes(keyword));
  
  // Check if there's a significant change in budget values (indicating intentional change)
  const existingBudget = currentSlots.budget || {};
  const newBudget = newData.budget || {};
  
  const hasSignificantChange = (
    (existingBudget.target_price && newBudget.target_price && Math.abs(existingBudget.target_price - newBudget.target_price) > 1000) ||
    (existingBudget.max_price && newBudget.max_price && Math.abs(existingBudget.max_price - newBudget.max_price) > 1000) ||
    (!existingBudget.target_price && newBudget.target_price) ||
    (!existingBudget.max_price && newBudget.max_price)
  );
  
  // Allow budget update if:
  // 1. No existing budget (first time setting)
  // 2. Message contains explicit budget keywords
  // 3. There's a significant change in budget values
  const isExplicit = !currentSlots.budget || hasBudgetKeywords || hasSignificantChange;
  
  console.log('?? Budget explicit check:', {
    userMessage: userMessage,
    hasBudgetKeywords: hasBudgetKeywords,
    hasSignificantChange: hasSignificantChange,
    existingBudget: existingBudget,
    newBudget: newBudget,
    isExplicit: isExplicit
  });
  
  return isExplicit;
  }



