  // ? NEW: Smart "More Options" system with criteria analysis and relaxation suggestions
  async handleMoreOptionsRequest(conversationContext, userMessage) {
    console.log('?? SMART MORE OPTIONS: Analyzing current criteria and suggesting relaxations');
    
    try {
      // Get current criteria from DAIVESTEPS
      const step1 = conversationContext.Daivesteps?.[1];
      const step2 = conversationContext.Daivesteps?.[2];
      const step3 = conversationContext.Daivesteps?.[3];
      
      const currentCriteria = {
        vehicleType: step1?.vehicle_type || step3?.slots?.VehicleSelection?.type || 'SUV',
        condition: step1?.vehicle_condition || step3?.slots?.VehicleSelection?.condition || 'pre-owned',
        maxPrice: step2?.slots?.budget?.max_price || step2?.slots?.budget?.target_price || 50000,
        make: step1?.make || step3?.slots?.VehicleSelection?.make,
        model: step1?.model || step3?.slots?.VehicleSelection?.model,
        colorTone: step1?.color_tone || step3?.slots?.VehicleSelection?.color_tone
      };
      
      console.log('?? Current criteria:', currentCriteria);
      
      // Check if there are more vehicles with exact same criteria
      if (!this.inventoryService) {
        console.error('? No inventory service available');
        return this.generateMoreOptionsFallbackResponse(currentCriteria);
      }
      
      const exactMatches = await this.inventoryService.searchVehiclesComprehensive({
        vehicleType: currentCriteria.vehicleType,
        budget: currentCriteria.maxPrice,
        condition: currentCriteria.condition
      }, null);
      
      console.log(`?? Exact matches found: ${exactMatches.length} vehicles`);
      
      // If we have more exact matches, show them
      if (exactMatches.length > 0) {
        console.log('? More exact matches available - showing additional vehicles');
        return {
          hasMoreExactMatches: true,
          additionalVehicles: exactMatches,
          response: `Great! I found ${exactMatches.length} more ${currentCriteria.vehicleType} options that match your criteria. Here are additional vehicles for you to consider:`
        };
      }
      
      // No more exact matches - suggest criteria relaxations
      console.log('?? No more exact matches - suggesting criteria relaxations');
      return await this.suggestCriteriaRelaxations(currentCriteria);
      
    } catch (error) {
      console.error('? Error in smart more options handling:', error);
      return this.generateMoreOptionsFallbackResponse({});
    }
  }

  // ? NEW: Suggest criteria relaxations when no more exact matches
  async suggestCriteriaRelaxations(currentCriteria) {
    console.log('?? SUGGESTING CRITERIA RELAXATIONS');
    
    const suggestions = [];
    const relaxationOrder = [
      {
        type: 'budget',
        description: 'budget increase',
        action: () => this.suggestBudgetRelaxation(currentCriteria),
        priority: 1
      },
      {
        type: 'vehicleType',
        description: 'vehicle type expansion',
        action: () => this.suggestVehicleTypeRelaxation(currentCriteria),
        priority: 2
      },
      {
        type: 'condition',
        description: 'condition flexibility',
        action: () => this.suggestConditionRelaxation(currentCriteria),
        priority: 3
      },
      {
        type: 'make',
        description: 'make expansion',
        action: () => this.suggestMakeRelaxation(currentCriteria),
        priority: 4
      }
    ];
    
    // Try each relaxation in priority order
    for (const relaxation of relaxationOrder) {
      try {
        const suggestion = await relaxation.action();
        if (suggestion && suggestion.hasOptions) {
          suggestions.push(suggestion);
          console.log(`? Found ${relaxation.description} options: ${suggestion.count} vehicles`);
        }
      } catch (error) {
        console.log(`?? ${relaxation.description} failed:`, error.message);
      }
    }
    
    if (suggestions.length > 0) {
      // Return the best suggestion (highest priority)
      const bestSuggestion = suggestions[0];
      console.log(`?? Best suggestion: ${bestSuggestion.type} - ${bestSuggestion.count} vehicles`);
      
      return {
        hasMoreExactMatches: false,
        hasRelaxedMatches: true,
        suggestion: bestSuggestion,
        response: bestSuggestion.message,
        relaxedCriteria: bestSuggestion.relaxedCriteria,
        additionalVehicles: bestSuggestion.vehicles
      };
    }
    
    // No relaxations found
    return {
      hasMoreExactMatches: false,
      hasRelaxedMatches: false,
      response: "I've shown you all the vehicles that match your current criteria. Would you like to adjust your preferences? For example, I could help you explore different vehicle types, adjust your budget, or look at other makes and models."
    };
  }

  // ? NEW: Suggest budget relaxation
  async suggestBudgetRelaxation(currentCriteria) {
    const budgetIncreases = [5000, 10000, 15000]; // $5k, $10k, $15k increases
    
    for (const increase of budgetIncreases) {
      const relaxedBudget = currentCriteria.maxPrice + increase;
      const vehicles = await this.inventoryService.searchVehiclesComprehensive({
        vehicleType: currentCriteria.vehicleType,
        budget: relaxedBudget,
        condition: currentCriteria.condition
      }, null);
      
      if (vehicles.length > 0) {
        return {
          type: 'budget',
          count: vehicles.length,
          hasOptions: true,
          vehicles: vehicles,
          relaxedCriteria: { ...currentCriteria, maxPrice: relaxedBudget },
          message: `Would you consider increasing your budget to $${relaxedBudget.toLocaleString()}? I have ${vehicles.length} more ${currentCriteria.vehicleType} options in that range that might interest you.`
        };
      }
    }
    
    return { hasOptions: false };
  }

