  async handlePurchaseCommitmentStepOptimized(userMessage, intentResult, conversationContext, slots) {
    console.log('? Handling Purchase Commitment Step (Simplified Mandatory Slots Version)');

    // Block purchase close until finance application link is actually sent.
    if (this._needsApplicationCompletion(conversationContext)) {
      console.log('?? Purchase blocked ? application pending, handing off to qualification');
      conversationContext.currentJourneyStep = 'qualification';
      return await this.handleQualificationStepOptimized(userMessage, intentResult, conversationContext, slots);
    }
  
    // -------------------------------------
    // 1?? Initialize Step Structure
    // -------------------------------------
    conversationContext.Daivesteps = conversationContext.Daivesteps || {};
    conversationContext.Daivesteps[7] = conversationContext.Daivesteps[7] || { slots: {} };
    const step = conversationContext.Daivesteps[7];
    step.slots.purchase_commitment = step.slots.purchase_commitment || {};
  
    const lowerMsg = userMessage.toLowerCase();
  
    // -------------------------------------
    // 2?? Sync Payment Mode from Qualification Step
    // -------------------------------------
    const qualificationStep = conversationContext.Daivesteps?.[6];
    let paymentMode =
      qualificationStep?.slots?.finance?.preferred_method ||
      qualificationStep?.slots?.qualification?.financing_method ||
      qualificationStep?.slots?.finance?.mode ||
      qualificationStep?.slots?.qualification?.credit_situation ||
      qualificationStep?.slots?.payment_mode;
  
    // Normalize payment keywords
    if (paymentMode === 'cash_buyer') paymentMode = 'cash';
    if (paymentMode === 'needs_financing') paymentMode = 'financing';
    if (paymentMode === 'lease_candidate') paymentMode = 'lease';
  
    // Detect override from current message (in case user reaffirms)
    if (lowerMsg.includes('cash')) paymentMode = 'cash';
    else if (lowerMsg.includes('finance')) paymentMode = 'financing';
    else if (lowerMsg.includes('lease')) paymentMode = 'lease';
    else if (lowerMsg.includes('cheque') || lowerMsg.includes('check')) paymentMode = 'cheque';
  
    // -------------------------------------
    // 3?? Detect Purchase Decision
    // -------------------------------------
    let purchaseDecision = null;
    if (/(yes|okay|ok|sure|alright|sounds good|let'?s go|go ahead|buy|purchase|ready|proceed|finalize|deal|i'?ll take it|let'?s do it|commit|how do i|how\?|tell me|next step)/i.test(lowerMsg)) {
      purchaseDecision = 'confirmed';
    } else if (/(no|not ready|not sure|think about|maybe later|need time)/i.test(lowerMsg)) {
      purchaseDecision = 'declined';
    }

    // For cash buyers who have already confirmed payment method: treat any non-negative message as confirmed
    if (!purchaseDecision && paymentMode === 'cash') {
      purchaseDecision = 'confirmed';
    }
  
    // -------------------------------------
    // 4?? Update Step Slots
    // -------------------------------------
    if (paymentMode) step.slots.purchase_commitment.payment_mode = paymentMode;
    if (purchaseDecision) step.slots.purchase_commitment.purchase_decision = purchaseDecision;
  
    const hasPaymentMode = !!step.slots.purchase_commitment.payment_mode;
    const hasPurchaseDecision = !!step.slots.purchase_commitment.purchase_decision;
  
    console.log('?? Purchase Commitment Slot Status:', {
      hasPaymentMode,
      hasPurchaseDecision,
      paymentMode,
      purchaseDecision
    });
  
    // -------------------------------------
    // 5?? Get Vehicle Description
    // -------------------------------------
    const vehicle = this.getSelectedVehicle(conversationContext);
    const vehicleDescription = vehicle
      ? `${vehicle.year} ${vehicle.make} ${vehicle.model}`
      : 'your selected vehicle';
  
    // -------------------------------------
    // 6?? Handle Outcomes
    // -------------------------------------
    // ? CASE A: All mandatory slots filled
    if (hasPaymentMode && hasPurchaseDecision) {
      const _finMethod = (qualificationStep?.slots?.qualification?.financing_method || paymentMode || '').toLowerCase();
      const _isFinanced = ['finance', 'financing', 'lease', 'needs_financing', 'lease_candidate'].includes(_finMethod);
      const _linkSent = qualificationStep?.slots?.application?.link_sent === true;
      if (_isFinanced && !_linkSent) {
        console.log('?? Purchase confirm blocked ? finance application not sent yet');
        conversationContext.currentJourneyStep = 'qualification';
        return await this.handleQualificationStepOptimized(userMessage, intentResult, conversationContext, slots);
      }

      step.status = 'completed';
      step.completedAt = new Date().toISOString();
      conversationContext.currentJourneyStep = 'completed';
      conversationContext.Daivesteps[7] = step;
      if (conversationContext.stepCompleted) {
        conversationContext.stepCompleted.purchase_commitment = true;
      }
  
      // Next-step messaging based on payment type
      let nextSteps = '';
      if (paymentMode === 'financing' || paymentMode === 'lease') {
        nextSteps =
          ' Our Finance Manager will now prepare your paperwork and confirm delivery timing.';
      } else if (paymentMode === 'cash' || paymentMode === 'cheque') {
        nextSteps =
          ' We?ll finalize your sales documents and schedule a convenient handover for your vehicle.';
      } else {
        nextSteps =
          ' Our Sales Manager will reach out shortly to finalize paperwork and confirm your delivery.';
      }
  
      if (purchaseDecision === 'confirmed') {
        console.log(`? Purchase confirmed for ${vehicleDescription} via ${paymentMode}`);
        return {
          response: `Fantastic! Your purchase of the ${vehicleDescription} is confirmed.${nextSteps} You're just a few steps away from driving home in your new vehicle! ??`,
          agentType: 'Sales Manager',
          conversationContext,
          purchaseCommitmentCompleted: true
        };
      } else {
        console.log(`? Purchase declined for ${vehicleDescription}.`);
        return {
          response: `No worries! Take your time to decide. The ${vehicleDescription} will be here when you're ready, and I can hold your preferred terms if you'd like.`,
          agentType: 'Sales Manager',
          conversationContext,
          purchaseCommitmentCompleted: false
        };
      }
    }
  
    // ?? CASE B: Missing purchase decision
    if (!hasPurchaseDecision) {
      return {
        response: `Are you ready to move forward with purchasing the ${vehicleDescription}? We already have your ${paymentMode || 'payment'} details from earlier, so we can finalize everything quickly.`,
        agentType: 'Sales Manager',
        conversationContext
      };
    }
  
    // ?? CASE C: Missing payment mode
    if (!hasPaymentMode) {
      return {
        response: `Would you like to complete your purchase using cash, financing, or lease? Once confirmed, we?ll finalize your ${vehicleDescription} right away.`,
        agentType: 'Sales Manager',
        conversationContext
      };
    }
  
    // Fallback
    return {
      response: 'Let?s go over your final purchase details and get you set up to complete your new vehicle purchase.',
      agentType: 'Sales Manager',
      conversationContext
    };
  }
  
